spec.expr:
max by (instance, job) (
  xui_exporter_scrape_duration_seconds{
    instance="${instance}",
    source=~"grpc|expvars"
  }
)

(100 * exp(
  -5 * (sum_over_time(xui_observatory_outbound_probe_failed_samples{instance="${instance}"}[$__range]) / sum_over_time(xui_observatory_outbound_probe_samples{instance="${instance}"}[$__range]))
  - 0.6 * (quantile_over_time(0.95, xui_observatory_outbound_rtt_mean_seconds{instance="${instance}"}[$__range]) - quantile_over_time(0.50, xui_observatory_outbound_rtt_mean_seconds{instance="${instance}"}[$__range]))
) * (clamp(130 - 100 * quantile_over_time(0.50, xui_observatory_outbound_rtt_mean_seconds{instance="${instance}"}[$__range]), 0, 100) / 100) ^ 0.20)
and on (outbound) max by (outbound) (
  xui_balancer_outbound_selected{instance="${instance}",balancer=~"${balancer}",outbound!=""}
)

((xui_observatory_outbound_alive{instance="${instance}"} * (1 + (xui_observatory_outbound_probe_failed_samples{instance="${instance}"} == bool 0)))
or (xui_observatory_outbound_alive{instance="${instance}"} * 2))
and on (outbound) max by (outbound) (
  xui_balancer_outbound_selected{instance="${instance}",balancer=~"${balancer}",outbound!=""}
)

(
  (xui_balancer_outbound_selected{instance="${instance}", balancer=~"${balancer}", role="fallback", outbound!=""} == 1)
  * on (instance, balancer) group_left()
  (
    ((xui_balancer_health{instance="${instance}", balancer=~"${balancer}"} == 1) * 3)
    or
    xui_balancer_health{instance="${instance}", balancer=~"${balancer}"}
  )
)
or
(
  xui_balancer_outbound_selected{instance="${instance}", balancer=~"${balancer}", role="fallback", outbound!=""} * 0 + 21
)

(
  (xui_balancer_outbound_selected{instance="${instance}", balancer=~"${balancer}", role="override", outbound!=""} == 1)
  * on (instance, balancer) group_left()
  (
    ((xui_balancer_health{instance="${instance}", balancer=~"${balancer}"} == 1) * 3)
    or
    xui_balancer_health{instance="${instance}", balancer=~"${balancer}"}
  )
)
or
(
  xui_balancer_outbound_selected{instance="${instance}", balancer=~"${balancer}", role="override", outbound!=""} * 0 + 21
)
